package apicontract

// AccessTools declares the access service operations.
type AccessTools struct {
	SecretPut                Binding[SecretPutArgs, Receipt]                  `tool:"secret_put" summary:"Write a secret for an approved step." desc:"Write a secret for an approved repository, file and step; audit records secret.put.requested before writing. Send private bytes only through the authenticated POST body at /api/secrets/put." access:"unscoped_admin" mutation:"true" post:"/api/secrets/put" bytes:"2097152" check:"audit_list"`
	AccessAllow              Binding[AccessAllowArgs, Grant]                  `tool:"access_allow" summary:"Approve a secret access request." desc:"Approve a pending secret access request for the exact repository, file, step and path. Read access_list to confirm the resulting grant." access:"unscoped_admin" mutation:"true" admin:"access-allow" bytes:"131072" check:"access_list"`
	AccessDismiss            Binding[AccessDismissArgs, Receipt]              `tool:"access_dismiss" summary:"Dismiss a secret access request." desc:"Dismiss a pending secret access request. Approved or revoked grants must use access_revoke; dismissal cannot hide a deletion retry target. Read access_list to check remaining requests." access:"unscoped_admin" mutation:"true" check:"access_list"`
	AccessList               Binding[AccessListArgs, GrantPage]               `tool:"access_list" summary:"List visible secret access requests and grants." desc:"List secret access requests and grants visible to this caller. Inspect the exact path and step before asking an administrator to approve access." get:"/api/grants" bytes:"131072"`
	AccessRevoke             Binding[AccessRevokeArgs, Receipt]               `tool:"access_revoke" summary:"Revoke a secret access grant." desc:"Revoke a grant. Stored-secret grants delete the exact path from both CI and release accounts for that tuple. If deletion fails, the grant stays revoked; read the public store detail, repair it and repeat this revoke. Other grant kinds do not delete values. Read access_list to confirm authority." access:"unscoped_admin" mutation:"true" admin:"access-revoke" bytes:"131072" check:"access_list"`
	WorkflowCapabilityGet    Binding[WorkflowCapabilityGetArgs, Capability]   `tool:"workflow_capability_get" summary:"Read approved native permissions for a workflow." desc:"Read the execution capability approved for a repository workflow. Inspect the native resource kinds before requesting a change."`
	WorkflowCapabilityGrant  Binding[WorkflowCapabilityGrantArgs, Capability] `tool:"workflow_capability_grant" summary:"Approve workflow execution permissions." desc:"Approve the exact namespace, service account and native resource operations for a workflow. Use workflow_capability_get to verify its scope." access:"unscoped_admin" mutation:"true" check:"workflow_capability_get"`
	WorkflowCapabilityRevoke Binding[WorkflowCapabilityRevokeArgs, Receipt]   `tool:"workflow_capability_revoke" summary:"Revoke workflow execution permissions." desc:"Revoke the approved execution capability for a repository workflow. Use workflow_capability_get to verify the resulting authority." access:"unscoped_admin" mutation:"true" check:"workflow_capability_get"`
}
